mapper.select:
SELECT BP.id as pointid, BC.*,BP.*,bld.create_time as mTime FROM base_company BC LEFT JOIN base_point BP ON BP.company_id = BC.id LEFT JOIN bu_lampblack_data_131000_now bld on BP.point_mac = bld.point_mac where 1=1
AND BC.id in
#{item}
AND BP.fid_region = #{fidRegion}
order by BC.id desc

